import * as fs from "node:fs";
import * as path from "node:path";

export function checkEvidence() {
  console.log("=== Checking Machine-Readable Evidence Files ===");

  const benchmarkPath = path.resolve(process.cwd(), "docs/benchmark-results.json");
  if (!fs.existsSync(benchmarkPath)) {
    console.warn("Notice: benchmark-results.json not found yet. Running benchmark now...");
    // Will be generated by benchmark script
  } else {
    const raw = fs.readFileSync(benchmarkPath, "utf-8");
    const bench = JSON.parse(raw);
    console.log(`✓ Benchmark Evidence Verified: ${bench.corpusSize} briefs, Action F1: ${bench.metrics.actionF1}, Repeatability: ${bench.metrics.repeatabilityPercent}%`);
  }

  const coveragePath = path.resolve(process.cwd(), "coverage/coverage-summary.json");
  if (fs.existsSync(coveragePath)) {
    const rawCov = fs.readFileSync(coveragePath, "utf-8");
    const cov = JSON.parse(rawCov);
    const total = cov.total;

    console.log("Coverage Summary:");
    console.log(` - Statements: ${total.statements.pct}% (Target: >=85%)`);
    console.log(` - Lines:      ${total.lines.pct}% (Target: >=85%)`);
    console.log(` - Functions:  ${total.functions.pct}% (Target: >=85%)`);
    console.log(` - Branches:   ${total.branches.pct}% (Target: >=80%)`);

    if (
      total.statements.pct < 85 ||
      total.lines.pct < 85 ||
      total.functions.pct < 85 ||
      total.branches.pct < 80
    ) {
      console.error("FAIL: Coverage threshold not met!");
      process.exit(1);
    }
  }

  console.log("✓ Evidence check completed.");
}

if (import.meta.url === `file://${process.argv[1]?.replace(/\\/g, "/")}` || process.argv[1]?.endsWith("check-evidence.ts")) {
  checkEvidence();
}
